import{_ as a,c as i,o as e,af as l}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"《易傳》簡介","description":"易傳 - 《易傳》簡介","frontmatter":{"title":"《易傳》簡介","description":"易傳 - 《易傳》簡介"},"headers":[],"relativePath":"classics/yizhuan/001.md","filePath":"classics/yizhuan/001.md"}'),t={name:"classics/yizhuan/001.md"};function s(r,p,n,c,_,o){return e(),i("div",null,[...p[0]||(p[0]=[l('<h1 id="《易傳》簡介" tabindex="-1">《易傳》簡介 <a class="header-anchor" href="#《易傳》簡介" aria-label="Permalink to “《易傳》簡介”">​</a></h1><p>易學包括《經》和《傳》兩部分。《易傳》是一部戰國時期解說和發揮《周易》的論文集，其學說據說本於孔子，具體成於孔子後學之手。《易傳》共7種10篇，它們是《彖傳》上下篇、《象傳》上下篇、《文言傳》、《繫辭傳》上下篇、《說卦傳》、《序卦傳》和《雜卦傳》。自漢代起，它們又被稱為“十翼”。</p><p>《周易》是憂患之書，是道德教訓之書，是君子之書，讀《易》要於憂患中提高道德境界，以此作為化兇為吉的手段。</p><p>上古有三易</p><p>周禮·春官·太卜：“掌三易之法，一曰連山；二曰歸藏；三曰周易”。三易，即《連山》、《歸藏》和《周易》，是古代中國的三部重要易書。</p><p>《連山》據傳為夏代易書，而《歸藏》則被認為是殷代作品。這兩部作品的具體內容和成書時代存在爭議，但它們對於理解古代中國的哲學思想和占卜文化具有重要意義。</p><p>《周易》最為人所知，傳統認為是周文王姬昌所作，包含《經》和《傳》兩部分，闡述宇宙變化和人生吉凶，是中國古代哲學和占卜文化的重要組成部分。三易作為文化遺產，展現了古代人們對宇宙和人生的理解，對研究古代中國社會、文化和哲學具有重要價值。</p><p>易經三古四聖</p><p>易經博大精深，其傳承跨越了上古、中古和下古三個歷史時期，並由四位聖人共同發揚光大，他們分別是：上古的伏羲，他開創了易經的基本框架；中古的周文王姬昌，他繼承並發展了易經，使得其更加完善；而周文王的兒子周公姬旦，也對易經的推廣和解釋做出了重要貢獻；最後，下古的孔子，他深入研究和解讀易經，使其成為了中華文化的重要組成部分。這四位聖人被尊稱為“四聖”，他們的貢獻使得易經得以流傳至今，成為中華文化的瑰寶。</p><p>易傳結構圖</p><p>《易傳》也稱為“十翼”，是對《易經》經文的解釋和擴展，共包括十篇內容，但這十篇實際由七部分組成：</p><ul><li><p>《彖傳》：分為上下兩篇，主要解釋每個卦的卦辭，揭示卦的基本性質和意義。</p></li><li><p>《象傳》：也分為上下兩篇，對卦象進行解說，包括卦象所象徵的事物和情境。</p></li><li><p>《繫辭傳》：同樣分為上下兩篇，是對《易經》整體思想、方法和占卜活動的深入闡釋和評論。</p></li><li><p>《文言傳》：是對特定卦爻辭的進一步解釋和闡述，幫助讀者更深入地理解這些卦辭的含義。</p></li><li><p>《說卦傳》：解釋八卦所象徵的各種事物，為理解卦象提供具體的背景和意義。</p></li><li><p>《序卦傳》：對六十四卦的排列順序進行說明，揭示各卦之間的內在聯繫和邏輯關係。</p></li><li><p>《雜卦傳》：是對各卦的雜說，補充了其他各傳所未盡之處，提供了更全面的卦象解釋和觀點。</p></li></ul><p>這七部分合起來就是“十翼”，它們共同構成了對《易經》經文的詳細解釋和擴展，為理解和研究《易經》提供了重要的參考。</p>',13)])])}const h=a(t,[["render",s]]);export{f as __pageData,h as default};
